"""Units: the only place Fusion's internal units are converted.

Fusion's API works in centimetres, square and cubic centimetres, and radians, whatever the
design's display units. The IR stores lengths in millimetres, areas in mm², volumes in mm³ and
angles in degrees. Expressions are never converted: they are Fusion's own text (with units),
which SolidCraft's expressions read too.

Stdlib only; this module is copied into the Fusion add-in (tools/sync_addin.py).
"""

from __future__ import annotations

import math
from collections.abc import Iterable

CM_TO_MM = 10.0
CM2_TO_MM2 = 100.0
CM3_TO_MM3 = 1000.0


def mm(cm_value: float, ndigits: int = 6) -> float:
	"""A length in Fusion's internal cm, as mm."""
	return round(cm_value * CM_TO_MM, ndigits)


def mm2(cm2_value: float, ndigits: int = 4) -> float:
	return round(cm2_value * CM2_TO_MM2, ndigits)


def mm3(cm3_value: float, ndigits: int = 3) -> float:
	return round(cm3_value * CM3_TO_MM3, ndigits)


def deg(rad_value: float, ndigits: int = 9) -> float:
	return round(math.degrees(rad_value), ndigits)


def matrix_mm(cm_array: Iterable[float], ndigits: int = 9) -> list[float]:
	"""Fusion's row-major 4x4 (translation in cm) as one with the translation in mm."""
	out = [round(float(v), ndigits) for v in cm_array]
	for i in (3, 7, 11):
		out[i] = round(out[i] * CM_TO_MM, ndigits)
	return out
